// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * The simple purchase (model purchase@1): on a card surface, the heading and a description beside the price, one
 * action and a note. Axes: layout (panel: the copy at the start, the price and the action at the end from md up,
 * centered: one centred column).
 */
import { type ReactNode } from "react";
import { Block, Box, Container, LinkButton, Stack, Text, Title } from "../compose";
import { cn, urlOf } from "../utils";

export type PurchaseSimpleProps = {
  id: string;
  title: string;
  description?: string;
  price: string;
  note?: string;
  actionLabel?: string;
  actionHref?: string;
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  layout?: "panel" | "centered";
  landmarkLabel?: string;
};

export function PurchaseSimple({
  id,
  title,
  description = "",
  price,
  note = "",
  actionLabel = "",
  actionHref = "",
  level = 2,
  padding = "standard",
  layout = "panel",
  landmarkLabel,
}: PurchaseSimpleProps) {
  const titleId = id + "-title";
  const box =
    (layout as string) === "panel" ? "md:flex-row md:items-center md:justify-between md:gap-12"
    : "items-center";
  const copyAlign = ((layout as string) === "panel") ? "start" : "center";
  const copyText = ((layout as string) === "panel") ? "text-start" : "text-center";
  const buy = ((layout as string) === "panel") ? "md:items-end" : "";
  return (
    <Block
      tag="section"
      className={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="purchase-simple"
    >
      <Container className="mx-auto w-full max-w-6xl px-4">
        <Box
          className={cn(
            "rounded bg-card p-6 text-card-foreground border border-border",
            "flex flex-col gap-8",
            box
          )}
        >
          <Stack gap="4" align={copyAlign} className="max-w-2xl">
            <Title as={level} size="2xl" weight="bold" className={cn("tracking-tight", copyText)} id={titleId}>
              {title}
            </Title>
            {description ? (
              <Text size="base" className={cn("text-muted-foreground", copyText)}>
                {description}
              </Text>
            ) : null}
          </Stack>
          <Stack gap="4" align={copyAlign} className={cn("shrink-0", buy)}>
            <Text size="3xl" weight="bold" className={cn("tracking-tight", copyText)}>
              {price}
            </Text>
            {(actionLabel && actionHref) ? (
              <LinkButton variant="default" size="lg" href={urlOf(actionHref)}>
                {actionLabel}
              </LinkButton>
            ) : null}
            {note ? (
              <Text size="xs" className={cn("text-muted-foreground", copyText)}>
                {note}
              </Text>
            ) : null}
          </Stack>
        </Box>
      </Container>
    </Block>
  );
}
